import{_ as e,o as t,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Реактивное программирование","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/types/reactive.md","filePath":"wiki/dev-commit/theory/programming/types/reactive.md"}'),s={name:"wiki/dev-commit/theory/programming/types/reactive.md"};function o(r,a,n,c,p,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="реактивное-программирование" tabindex="-1">Реактивное программирование <a class="header-anchor" href="#реактивное-программирование" aria-label="Permalink to &quot;Реактивное программирование&quot;">​</a></h1><ul><li><strong>Reactive Programming</strong> - набор подходов пытающихся решить проблему Side Effects</li><li>Самой известной реализацией этой парадигмы является библиотека RxJS, использующая концепцию Reactive Streams</li></ul><hr><ul><li>Excel - как реактивная среда разработки</li><li>При задании формул, значения в ячейках зависят друг от друга. Это реактивное программирование в действии. При изменении значения в одной ячейке, зависимые ячейки пересчитываются автоматически</li></ul><hr><ul><li>React построен на парадигме реактивного программирования</li><li>Этот декларативный подход предлагает описывать данные в виде набора утверждений</li><li>Изменение одного из параметров ведёт за собой автоматический пересчёт всех зависимостей</li></ul><h4 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h4><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">a </span><span style="color:#0184BC;">=</span><span style="color:#383A42;"> b </span><span style="color:#0184BC;">+</span><span style="color:#383A42;"> c</span></span></code></pre></div><ol><li>В императивном программировании выражение означает: взять текущие значения b и c, сложить их и присвоить a результат. Дальнейшие изменения параметров b и c не влияют на a</li><li>В реактивном программировании выражение означает: a есть сумма b и с. Если b или c изменятся в будущем, это отразится на величине a</li></ol>',9)])])}const h=e(s,[["render",o]]);export{_ as __pageData,h as default};
